const nmapItems = $("Extract CVE IDs").all();

return items.map(item => {
  const data = item.json;

  const cve = data.vulnerabilities?.[0]?.cve;

  if (!cve) {
    return {
      json: {
        error: "No CVE data found"
      }
    };
  }

  // Find the ORIGINAL Nmap finding that produced this CVE
  const nmapItem = nmapItems.find(item =>
    item.json.cveId === cve.id
  );

  const nmap = nmapItem?.json || {};

  // -------------------------
  // Get CVSS data
  // -------------------------

  const metric =
    cve.metrics?.cvssMetricV31?.[0] ||
    cve.metrics?.cvssMetricV30?.[0] ||
    cve.metrics?.cvssMetricV2?.[0];

  const cvssData = metric?.cvssData;

  // -------------------------
  // Normalize severity
  // -------------------------

  let severity = metric?.baseSeverity || null;

  if (!severity && cvssData?.baseScore != null) {
    const score = Number(cvssData.baseScore);

    if (score >= 9.0) {
      severity = "CRITICAL";
    } else if (score >= 7.0) {
      severity = "HIGH";
    } else if (score >= 4.0) {
      severity = "MEDIUM";
    } else if (score > 0) {
      severity = "LOW";
    } else {
      severity = "NONE";
    }
  }

  // -------------------------
  // Description
  // -------------------------

  const description =
    cve.descriptions?.find(d => d.lang === "en")?.value ||
    cve.descriptions?.[0]?.value ||
    null;

  // -------------------------
  // CWE
  // -------------------------

  const cwe =
    cve.weaknesses?.[0]?.description
      ?.find(d => d.lang === "en")?.value ||
    null;

  // -------------------------
  // Final combined object
  // -------------------------

  return {
    json: {

      // =========================
      // NMAP CONTEXT
      // =========================

      host: nmap.ip ?? null,
      port: nmap.port ?? null,
      protocol: nmap.protocol ?? null,
      service: nmap.service ?? null,
      product: nmap.product ?? null,
      version: nmap.version ?? null,
      scriptId: nmap.scriptId ?? null,
      finding: nmap.finding ?? null,

      // =========================
      // CVE INFORMATION
      // =========================

      cveId: cve.id,

      description,

      published: cve.published,

      lastModified: cve.lastModified,

      // =========================
      // CVSS
      // =========================

      cvss: cvssData
        ? {
            version: cvssData.version,
            score: cvssData.baseScore,
            severity,
            vector: cvssData.vectorString
          }
        : null,

      // =========================
      // CWE
      // =========================

      cwe

    }
  };
});

const items = $input.all();

const priorityScore = {
  "Immediate": 4,
  "High": 3,
  "Medium": 2,
  "Low": 1
};

const riskScore = {
  "Critical": 4,
  "High": 3,
  "Medium": 2,
  "Low": 1
};

// ------------------------------------
// 1. Normalize all vulnerability items
// ------------------------------------

const findings = items.map(item => {
  const data = item.json;
  const analysis = data.output || data;

  return {
    host: analysis.host ?? data.host ?? null,
    port: analysis.port ?? data.port ?? null,
    protocol: analysis.protocol ?? data.protocol ?? null,
    service: analysis.service ?? data.service ?? null,
    product: analysis.product ?? data.product ?? null,
    version: analysis.version ?? data.version ?? null,

    scriptId: analysis.scriptId ?? data.scriptId ?? null,
    finding: analysis.finding ?? data.finding ?? null,

    cveId: analysis.cveId ?? data.cveId ?? null,
    description: analysis.description ?? data.description ?? null,
    published: analysis.published ?? data.published ?? null,
    lastModified: analysis.lastModified ?? data.lastModified ?? null,

    cvss: analysis.cvss ?? data.cvss ?? null,
    cwe: analysis.cwe ?? data.cwe ?? null,

    riskLevel: analysis.risk_level ?? null,
    status: analysis.status ?? null,
    exploitability: analysis.exploitability ?? null,
    potentialImpact: analysis.potential_impact ?? null,
    hostRelevance: analysis.host_relevance ?? null,

    remediation: Array.isArray(analysis.remediation)
      ? analysis.remediation
      : [],

    priority: analysis.priority ?? null,
    confidence: analysis.confidence ?? null,
    summary: analysis.summary ?? null
  };
});

// ------------------------------------
// 2. Add prioritization scores
// ------------------------------------

for (const finding of findings) {
  finding.priorityScore =
    priorityScore[finding.priority] ?? 0;

  finding.riskScore =
    riskScore[finding.riskLevel] ?? 0;
}

// ------------------------------------
// 3. Sort highest priority first
// ------------------------------------

findings.sort((a, b) => {
  if (b.priorityScore !== a.priorityScore) {
    return b.priorityScore - a.priorityScore;
  }

  return b.riskScore - a.riskScore;
});

// ------------------------------------
// 4. Calculate report statistics
// ------------------------------------

const counts = {
  critical: 0,
  high: 0,
  medium: 0,
  low: 0
};

for (const finding of findings) {
  const risk = (finding.riskLevel || "").toLowerCase();

  if (risk === "critical") counts.critical++;
  else if (risk === "high") counts.high++;
  else if (risk === "medium") counts.medium++;
  else if (risk === "low") counts.low++;
}

// ------------------------------------
// 5. Determine overall risk
// ------------------------------------

let overallRisk = "Low";

if (counts.critical > 0) {
  overallRisk = "Critical";
} else if (counts.high > 0) {
  overallRisk = "High";
} else if (counts.medium > 0) {
  overallRisk = "Medium";
}

// ------------------------------------
// 6. Report metadata
// ------------------------------------

const host =
  findings.length > 0
    ? findings[0].host
    : null;

const report = {
  scanTarget: host,

  generatedAt: new Date().toISOString(),

  overallRisk,

  statistics: {
    totalFindings: findings.length,
    critical: counts.critical,
    high: counts.high,
    medium: counts.medium,
    low: counts.low
  },

  findings
};

// ------------------------------------
// 7. Return final report
// ------------------------------------

return [
  {
    json: report
  }
];

const data = $input.first().json;
const nmap = data.nmaprun;

const host = Array.isArray(nmap.host) ? nmap.host[0] : nmap.host;

if (!host) {
  throw new Error("No host found in Nmap output");
}

const toArray = (value) => {
  if (!value) return [];
  return Array.isArray(value) ? value : [value];
};

const ip = host.address?.addr ?? null;
const ports = toArray(host.ports?.port);

const results = [];

// -------------------------
// 1. Extract open ports
// -------------------------

for (const port of ports) {
  results.push({
    json: {
      type: "port",
      ip,
      protocol: port.protocol ?? null,
      port: port.portid ?? null,
      state: port.state?.state ?? null,
      service: port.service?.name ?? null,
      product: port.service?.product ?? null,
      version: port.service?.version ?? null
    }
  });
}

// -------------------------
// 2. Extract host vulnerability scripts
// -------------------------

const hostScripts = toArray(host.hostscript?.script);

for (const script of hostScripts) {

  // Try to identify which service the vulnerability belongs to
  const scriptText = `${script.id ?? ""} ${script.output ?? ""}`.toLowerCase();

  let matchingPort = null;

  // Look for a port whose service/product appears in the script
  for (const port of ports) {
    const service = (port.service?.name ?? "").toLowerCase();
    const product = (port.service?.product ?? "").toLowerCase();

    if (
      (service && scriptText.includes(service)) ||
      (product && scriptText.includes(product))
    ) {
      matchingPort = port;
      break;
    }
  }

  // Special handling for Samba/SMB vulnerabilities
  if (!matchingPort && (
    scriptText.includes("samba") ||
    scriptText.includes("smb")
  )) {
    matchingPort = ports.find(port =>
      ["445", "139"].includes(String(port.portid))
    ) ?? null;
  }

  results.push({
    json: {
      type: "vulnerability_check",
      ip,

      protocol: matchingPort?.protocol ?? null,
      port: matchingPort?.portid ?? null,
      state: matchingPort?.state?.state ?? null,

      service: matchingPort?.service?.name ?? null,
      product: matchingPort?.service?.product ?? null,
      version: matchingPort?.service?.version ?? null,

      scriptId: script.id ?? null,
      output: script.output ?? null
    }
  });
}

// -------------------------
// 3. Extract scripts attached to ports
// -------------------------

for (const port of ports) {
  const scripts = toArray(port.script);

  for (const script of scripts) {
    results.push({
      json: {
        type: "vulnerability_check",

        ip,
        protocol: port.protocol ?? null,
        port: port.portid ?? null,
        state: port.state?.state ?? null,

        service: port.service?.name ?? null,
        product: port.service?.product ?? null,
        version: port.service?.version ?? null,

        scriptId: script.id ?? null,
        output: script.output ?? null
      }
    });
  }
}

return results;

const items = $input.all();

const findings = [];

for (const item of items) {
  const data = item.json;

  const scriptId = data.scriptId || "";
  const output = data.output || "";

  // Ignore confirmed negative vulnerability checks
  if (
    output.toLowerCase() === "false" ||
    output.toLowerCase().includes("couldn't find any") ||
    output.toLowerCase().includes("no vulnerabilities")
  ) {
    continue;
  }

  findings.push({
    json: {
      ip: data.ip,
      port: data.port || null,
      protocol: data.protocol || null,
      service: data.service || null,
      scriptId,
      finding: output
    }
  });
}

return findings;

const items = $input.all();

return items.map(item => {
  const data = item.json;

  const scriptId = data.scriptId || "";
  const finding = data.finding || "";

  // Look for a CVE directly in the script ID or finding
  const cveMatch = `${scriptId} ${finding}`.match(/CVE-\d{4}-\d{4,7}/i);

  return {
    json: {
      ...data,
      cveId: cveMatch ? cveMatch[0].toUpperCase() : null
    }
  };
});
